screenPreview.querySelector('.screen-preview-close').addEventListener('click',()=>screenPreview.close());
screenPreview.addEventListener('click',event=>{if(event.target===screenPreview)screenPreview.close()});
function openScreenPreview(img){const previewImage=screenPreview.querySelector('img');previewImage.src=img.currentSrc||img.src;previewImage.alt=img.alt;screenPreview.showModal()}
content?.addEventListener('click',event=>{const img=event.target.closest('.screen-slot img');if(img&&img.naturalWidth)openScreenPreview(img)});
content?.addEventListener('keydown',event=>{const img=event.target.closest('.screen-slot img');if(img&&img.naturalWidth&&(event.key==='Enter'||event.key===' ')){event.preventDefault();openScreenPreview(img)}});
function renderGroupedScreens(id,screens,groups){const wide=['auth-flows','ihsan-connect','nexus-onboarding'].includes(id)?' screen-group-wide':'';return groups.map(group=>`<section class="screen-group${wide}"><header><p class="eyebrow">${group.title}</p><p>${group.description}</p></header><div class="screen-gallery${wide?' screen-gallery-wide':''}">${screens.slice(group.from,group.to).map((screen,index)=>{const n=group.from+index+1;const filename=`${id}-screen-${String(screen.assetNumber||n).padStart(2,'0')}.jpg`;const media=screen.pairs?`<div class="paired-screens">${screen.pairs.map(pair=>`<figure class="paired-screen"><figcaption>${pair.label}</figcaption>${slot(`assets/projects/${pair.filename}`,pair.label,'screen-slot')}<p class="screen-description">${pair.description}</p></figure>`).join('')}</div>`:slot(`assets/projects/${screen.image||filename}`,screen.title,'screen-slot');return `<figure id="${id}-screen-${String(n).padStart(2,'0')}" class="screen-card"><figcaption><span>${String(n).padStart(2,'0')}</span><b>${screen.title}</b></figcaption>${media}${screen.description&&!screen.pairs?`<p class="screen-description">${screen.description}</p>`:''}</figure>`}).join('')}</div></section>`).join('')}
