const portfolioTextOriginals=new WeakMap(),portfolioAttributeOriginals=new WeakMap();
function portfolioTranslatePhrase(source,language){
 const key=source.trim().replace(/\s+/g,' ');
 if(language==='fr'){
  const translated=portfolioFrenchProjectSupplement[key]??portfolioFrenchProjectCopy[key]??portfolioFrench[key]??portfolioFrenchAdditional[key];
  if(translated!==undefined)return translated;
  if(key==='Open navigation')return 'Ouvrir la navigation';
  if(key==='Close navigation')return 'Fermer la navigation';
  if(key==='Send message')return 'Envoyer le message';
  if(key==='Screen image preview')return 'Aper\u00e7u de l\u2019\u00e9cran';
  if(key==='View large image preview')return 'Agrandir l\u2019image';
  if(key==='Close image preview')return 'Fermer l\u2019aper\u00e7u';
  if(key==='Choose language')return 'Choisir la langue';
  const caseMatch=key.match(/^Open (.+) case study$/);if(caseMatch)return 'Ouvrir l\u2019\u00e9tude de cas '+caseMatch[1];
  const generic=key.match(/^A key screen in the (.+) experience, designed to make this step clear and easy to complete\.$/);if(generic)return '\u00c9cran cl\u00e9 de l\u2019exp\u00e9rience '+generic[1]+', con\u00e7u pour rendre cette \u00e9tape claire et simple.';
  return source;
 }
 if(language==='en-GB'&&portfolioEnglishUK)return portfolioEnglishUK[key]||source;
 return source;
}
function portfolioTranslateText(node){
 if(!node.parentElement||node.parentElement.closest('script,style,textarea,.typewriter-text,.site-tools'))return;
 if(!portfolioTextOriginals.has(node))portfolioTextOriginals.set(node,node.nodeValue);
 const original=portfolioTextOriginals.get(node),trimmed=original.trim();if(!trimmed)return;
 const section=node.parentElement.closest('.home-intro,.home-work');
 let translated=portfolioTranslatePhrase(trimmed,portfolioLanguage);
 // These headings split a single English phrase across separate inline nodes.
 // Translate the fragments in context so French reads naturally when reassembled.
 if(portfolioLanguage==='fr'&&section?.matches('.home-intro')&&trimmed==='to the')translated='à l’';
 if(portfolioLanguage==='fr'&&section?.matches('.pod-home-work')&&trimmed==='for')translated='pour';
 if(portfolioLanguage==='fr'&&section?.matches('.home-work:not(.pod-home-work)')){
  if(trimmed==='for')translated='pour répondre';
  if(trimmed==='everyday needs.')translated='aux besoins du quotidien.';
 }
 const leading=original.match(/^\s*/)[0],trailing=original.match(/\s*$/)[0],next=leading+translated+trailing;
 if(node.nodeValue!==next)node.nodeValue=next;
}
function portfolioTranslateElement(element){
 if(element.nodeType===Node.TEXT_NODE){portfolioTranslateText(element);return}
 if(element.nodeType!==Node.ELEMENT_NODE)return;
 const skip='.site-tools,.typewriter-text,script,style,title';if(element.matches(skip))return;
 const translateAttributes=node=>{for(const attr of ['aria-label','title','placeholder','alt','content','value']){if(!node.hasAttribute(attr))continue;let saved=portfolioAttributeOriginals.get(node);if(!saved){saved={};portfolioAttributeOriginals.set(node,saved)}if(!(attr in saved))saved[attr]=node.getAttribute(attr);const translated=portfolioTranslatePhrase(saved[attr],portfolioLanguage);if(node.getAttribute(attr)!==translated)node.setAttribute(attr,translated)}};
 for(const node of [element,...element.querySelectorAll('*')]){if(node.matches(skip)||node.closest(skip))continue;translateAttributes(node);for(const child of node.childNodes)if(child.nodeType===Node.TEXT_NODE)portfolioTranslateText(child)}
}
function portfolioApplyLanguage(language){
 portfolioLanguage=language==='fr'?'fr':'en-GB';document.documentElement.lang=portfolioLanguage;
 const title=document.querySelector('title');if(title){if(!title.dataset.originalTitle)title.dataset.originalTitle=title.textContent;title.textContent=portfolioTranslatePhrase(title.dataset.originalTitle,portfolioLanguage)}
 try{localStorage.setItem('portfolio-language',portfolioLanguage)}catch(e){}
 portfolioTranslateElement(document.documentElement);
 document.dispatchEvent(new CustomEvent('portfolio-language-change',{detail:{language:portfolioLanguage}}));
 document.querySelectorAll('.language-option').forEach(button=>{const active=button.dataset.language===portfolioLanguage;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});
 const control=document.querySelector('.language-control');if(control)control.setAttribute('aria-label',portfolioLanguage==='fr'?'Choisir la langue':'Choose language');
}
document.addEventListener('click',event=>{const button=event.target.closest('.language-option');if(button&&!button.disabled)portfolioApplyLanguage(button.dataset.language)});
portfolioApplyLanguage(portfolioLanguage);
const portfolioObserver=new MutationObserver(records=>records.forEach(record=>{if(record.type==='characterData')portfolioTranslateText(record.target);for(const node of record.addedNodes||[])portfolioTranslateElement(node)}));
portfolioObserver.observe(document.documentElement,{childList:true,subtree:true,characterData:true});
